How many times is "OS" printed when the following program runs? (Assume every fork() succeeds.)
```c
#include <stdio.h>
#include <unistd.h>
int main() {
    fork();
    fork();
    fork();
    printf("OS\n");
    return 0;
}
```

How many times is "hi" printed by the following program? (Assume every fork() succeeds and output is written immediately.)
```c
#include <stdio.h>
#include <unistd.h>
int main() {
    int i;
    for (i = 0; i < 3; i++) {
        fork();
        printf("hi\n");
    }
    return 0;
}
```

How many times is "A" printed by the following program? (Assume every fork() succeeds.)
```c
#include <stdio.h>
#include <unistd.h>
int main() {
    if (fork() || fork())
        fork();
    printf("A\n");
    return 0;
}
```

How many times is "Z" printed by the following program? (Assume every fork() succeeds.)
```c
#include <stdio.h>
#include <unistd.h>
int main() {
    int i;
    for (i = 0; i < 4; i++) {
        if (fork() == 0)
            break;
    }
    printf("Z\n");
    return 0;
}
```

What is the output of the following program? (Assume fork() succeeds.)
```c
#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
int main() {
    int x = 5;
    if (fork() == 0) {
        x = x + 10;
        printf("%d\n", x);
    } else {
        wait(NULL);
        x = x - 2;
        printf("%d\n", x);
    }
    return 0;
}
```

